Abaixo está um exemplo completo de bot em **Node.js + Telegraf** que faz uma contagem regressiva a partir de um tempo informado no formato **HH:MM**.  
Ele avisa a cada **30 minutos** quanto tempo falta e finaliza quando o tempo acaba.

## 1. Instale as dependências

```bash
npm init -y
npm install telegraf
```

## 2. Crie um arquivo `.env`

```env
TELEGRAM_BOT_TOKEN=SEU_TOKEN_AQUI
```

Você pode pegar o token no [@BotFather](https://t.me/BotFather).

---

## 3. Código do bot

Salve como `bot-tempo.js`:

```js
// ============================================
// Bot Telegram com Telegraf - Contador regressivo HH:MM
// ============================================
require('dotenv').config();
const { Telegraf, ParseMode } = require('telegraf');
const crypto = require('crypto');

const BOT_TOKEN = process.env.TELEGRAM_BOT_TOKEN;

if (!BOT_TOKEN) {
  console.error(
    'Não foi encontrado BOT_TOKEN. Crie um arquivo .env com:\n' +
      'TELEGRAM_BOT_TOKEN=SEU_TOKEN_AQUI'
  );
  process.exit(1);
}

const bot = new Telegraf(BOT_TOKEN);

// Armazena as contagens ativas no processo.
const contagens = new Map();

const INTERVALO_MS = 30 * 60 * 1000; // 30 minutos

function pad(v, qtd = 2) {
  return String(v).toString().padStart(qtd, '0');
}

/**
 * Valida entrada no formato HH:MM.
 * Ex.: 02:30 -> { totalSegundos: 7800, hora: 2, min: 30 }
 */
function parseHHMM(txt) {
  const limpo = (txt || '').trim().replace(/\s/g, '').toUpperCase();
  const m = limpo.match(/^(\d{2}):(\d{2})$/);
  if (!m) return null;

  const hora = Number(m[1]);
  const min = Number(m[2]);

  if (hora < 0 || hora > 23 || min < 0 || min > 59) return null;

  return {
    totalSegundos: hora * 3600 + min * 60,
    hora,
    min,
  };
}

const PEDIDO =
  'Olá! 👋 Use `/tempo` para criar uma contagem regressiva.\n' +
  'Passo 1: digite o tempo desejado no formato **HH:MM** (ex.: **02:30**).\n' +
  'A contagem enviará avisos a cada 30 minutos dizendo quanto tempo falta.';

bot.router.command('tempo', async (ctx) => {
  // Aguarda a resposta digitada pelo usuário.
  await ctx.reply(PEDIDO);
  const entrada = await ctx.wait().text;

  const resultado = parseHHMM(entrada);

  // Valida tempo válido e maior que zero.
  if (!resultado || resultado.totalSegundos <= 0) {
    await ctx.reply(
      '⚠️ Informe um tempo válido (mínimo 01:00).\n' +
        'Formato aceito: **HH:MM**\n' +
        'Exemplo: **02:30**',
      { parse_mode: ParseMode.HTML }
    );
    return;
  }

  const { totalSegundos, hora, min } = resultado;
  const duracaoHumana = `**${pad(hora)}h${pad(min)}min**`;
  const inicio = Date.now();
  const idUnico = `contagem_${crypto.randomUUID().slice(0, 8)}_${ctx.fromId}`;

  // Guarda os dados da contagem ativa.
  contagens.set(idUnico, {
    chatId: ctx.chat.id,
    userId: ctx.from.id,
    totalSegundos,
    inicio,
    proximoEnvio: null,
    timerId: null,
  });

  // Mensagem inicial da contagem.
  const inicioHtml = `
🎯 Contagem regressiva iniciada!

📅 Início: ${new Date(inicio).toLocaleString('pt-BR')}
⏳ Tempo solicitado: **${duracaoHumana}**
🕐 Avisos: a cada **30 minutos** informando quanto tempo falta.

Mantenha este comando aberto até a contagem terminar.`;

  try {
    await bot.telegram.sendMessage(ctx.chat.id, inicioHtml, { parse_mode: ParseMode.HTML });
  } catch (err) {
    console.error('Erro ao enviar mensagem inicial:', err);
  }

  // ==========================================
  // Controlador dos envios programados
  // ==========================================
  const tick = async () => {
    const agora = Date.now();
    const dado = contagens.get(idUnico);

    if (!dado) {
      // Contagem já foi removida/acabou.
      return;
    }

    try {
      if (dado.proximoEnvio && agora >= dado.proximoEnvio) {
        // Chegou a hora de enviar.
        const restantes = Math.max(0, Math.floor((inicio + totalSegundos) - agora));

        if (restantes <= 0) {
          // Tempo acabou.
          contagens.delete(idUnico);

          const concluido =
            `✅ Contagem concluída!\n` +
            `Você havia pedido **${duracaoHumana}**.\n` +
            `Início: ${new Date(inicio).toLocaleString('pt-BR')}`;

          try {
            await bot.telegram.sendMessage(ctx.chat.id, concluido, { parse_mode: ParseMode.HTML });
          } catch (err) {
            console.error('Erro na mensagem final:', err);
          }

          if (dado.timerId) {
            clearInterval(dado.timerId);
          }

          dado.proximoEnvio = null;
          return;
        }

        // Envia o aviso de tempo restante.
        const h = pad(Math.floor(restantes / 3600));
        const m = pad(Math.floor((restantes % 3600) / 60));
        const s = pad(restantes % 60);
        const corpo = `⏱️ Faltam **${h}:${m}:${s}** para terminar.`;

        try {
          await bot.telegram.sendMessage(ctx.chat.id, corpo, { parse_mode: ParseMode.HTML });
        } catch (err) {
          console.error('Erro ao enviar aviso:', err);
        }

        // Agenda o próximo envio.
        dado.proximoEnvio = agora + INTERVALO_MS;
        dado.timerId = setTimeout(tick, INTERVALO_MS);
      } else if (dado.proximoEnvio && agora < dado.proximoEnvio) {
        // Ainda não chegou a hora do próximo envio.
        const espera = Math.max(0, dado.proximoEnvio - agora);
        if (espera > 0) {
          dado.proximoEnvio = agora + espera;
          dado.timerId = setTimeout(tick, espera);
        }
      }
    } catch (err) {
      console.error('Erro no tick da contagem:', err);
    }
  };

  // Configura o primeiro horário de envio.
  const dadosInicio = contagens.get(idUnico);
  if (dadosInicio) {
    if (dadosInicio.totalSegundos > INTERVALO_MS) {
      // Mais de 30 minutos: primeiro aviso após 30 min.
      dadosInicio.proximoEnvio = inicio + INTERVALO_MS;
    } else if (dadosInicio.totalSegundos > 0) {
      // Menos ou igual a 30 min: aviso inicial + espera até o fim.
      dadosInicio.proximoEnvio = inicio + totalSegundos;
    }

    const esperaInicial = Math.max(0, dadosInicio.proximoEnvio - Date.now());
    if (esperaInicial > 0) {
      dadosInicio.timerId = setTimeout(tick, esperaInicial);
    } else {
      tick();
    }
  }
});

// ============================================
// Encerramento seguro do processo
// ============================================
const sair = async () => {
  console.log('Encerrando bot...');
  for (const [, dado] of contagens.entries()) {
    if (dado.timerId) {
      clearInterval(dado.timerId);
    }
  }
  contagens.clear();

  try {
    await bot.disconnect();
  } catch (e) {
    // Ignora erros de desconexão.
  }

  process.exit(0);
};

process.once('SIGINT', sair);
process.once('SIGTERM', sair);

console.log('Bot iniciado. Use /tempo para criar contagens regressivas.');
```

---

## Como usar

1. Cole seu token do BotFather em `TELEGRAM_BOT_TOKEN`.
2. Rode:

```bash
node bot-tempo.js
```

3. No Telegram, envie **`/tempo`**.
4. O bot pedirá o tempo no formato **HH:MM**.
5. Exemplo:

   - Você digita: `02:30`
   - O bot inicia a contagem.
   - Após 30 min, envia: `⏱️ Faltam **01:30:00** para terminar.`
   - Depois a cada 30 min, informa o tempo restante.
   - Quando acabar, mostra: `✅ Contagem concluída!`

---

### Observações importantes

- A validação aceita **apenas HH:MM com exatamente 2 dígitos**.
- Para tempos menores que 30 minutos, ele avisa inicialmente e depois pausa até o fim, sem repetições desnecessárias.
- Em produção, recomendo usar **Redis/PostgreSQL** para armazenar contagens ativas e evitar perda em restarts.
- Para desligar manualmente uma contagem ativa, seria necessário incrementar o código com um comando específico e comparar o ID da conversa.

