// arquivo: bot-tempo.js

require('dotenv').config();
const { Telegraf, ParseMode } = require('telegraf');
const crypto = require('crypto');

const BOT_TOKEN = process.env.TELEGRAM_BOT_TOKEN;

if (!BOT_TOKEN) {
  console.error('Não foi encontrado BOT_TOKEN. Crie um arquivo .env com: TELEGRAM_BOT_TOKEN=SEU_TOKEN_AQUI');
  process.exit(1);
}

const bot = new Telegraf(BOT_TOKEN);

// Guarda todas as contagens ativas no processo.
// Em produção, substitua por um banco de dados/Redis e limpe por lá.
const contagens = new Map();

const INTERVALO_MINUTOS = 30;
const INTERVALO_MS = INTERVALO_MINUTOS * 60 * 1000;

function pad(v, qtd = 2) {
  return String(v).toString().padStart(qtd, '0');
}

/**
 * Pega um valor no formato HH:MM e retorna { totalSegundos, hora, min }.
 * Só aceita exatamente dois dígitos antes e depois dos dois pontos.
 */
function parseHHMM(txt) {
  const limpo = (txt || '').trim().replace(/\s/g, '').toUpperCase();
  const m = limpo.match(/^(\d{2}):(\d{2})$/);
  if (!m) return null;
  const hora = Number(m[1]);
  const min = Number(m[2]);
  if (hora < 0 || hora > 23 || min < 0 || min > 59) return null;
  return {
    totalSegundos: (hora * 3600) + (min * 60),
    hora,
    min,
  };
}

// Mensagem de pedido inicial
const PEDIDO =
  'Olá! 👋 Use `/tempo` para criar uma contagem regressiva.\n' +
  'Passo 1: digite o tempo desejado no formato **HH:MM** (ex.: **02:30**).\n' +
  'A contagem avisará a cada 30 minutos quanto tempo falta.';

router.command('tempo', async (ctx) => {
  await ctx.reply(PEDIDO);

  // Aguarda a resposta digitada pelo usuário.
