    await ctx.reply(
      '⚠️ Formato inválido. Digite apenas números com exatamente dois dígitos e dois pontos, por exemplo: **02:30**.\n' +
        'Tente novamente.',
      { parse_mode: ParseMode.HTML } // talvez necessário
    );
    return;
  }

  const { totalSegundos, hora, min } = resultado;
  const duracaoHumana = `**${pad(hora)}h${pad(min)}min**`;
  const inicio = Date.now();
  const idUnico = `contagem_${crypto.randomUUID().slice(0, 8)}_${ctx.fromId}`;

  // Registra a contagem ativa.
  contagens.set(idUnico, {
    chatId: ctx.chat.id,
    userId: ctx.from.id,
    duracao: { hora, min },
    totalSegundos,
    inicio,
    timerId: null,
  });

  // Mensagem de início da contagem.
  const inicioHtml = `
🎯 Contagem regressiva iniciada!

📅 Início: ${new Date(inicio).toLocaleString('pt-BR')}
⏳ Tempo solicitado: **${duracaoHumana}**
🕐 Avisos: a cada **${INTERVALO_MINUTOS} minuto(s)**.

Mantenha este comando aberto até a contagem terminar.`;

  try {
    await bot.telegram.sendMessage(ctx.chat.id, inicioHtml, { parse_mode: ParseMode.HTML });
  } catch (err) {
    console.error('Erro ao enviar mensagem inicial:', err);
  }

  // Cronômetro principal.
